SELECT id,
        systemid,        systemorderid,        systemordertypeid,        public.clordid_to_guid(orderid)                          as orderid,        public.clordid_to_guid(parentorderid)                    as parentorderid,        public.clordid_to_guid(cancelorderid)                    as cancelorderid,        public.clordid_to_guid(contraorderid)                    as contraorderid,        public.clordid_to_guid(origorderid)                      as origorderid,        public.clordid_to_guid(replaceorderid)                   as replaceorderid,        status,        createdatetime::timestamptz at time zone 'US/Central'    as createdatetime,        approveddatetime::timestamptz,        dtclearbookdatetime::timestamptz,        firstfilldatetime::timestamptz at time zone 'US/Central' as firstfilldatetime,        lastfilldatetime::timestamptz at time zone 'US/Central'  as lastfilldatetime,        updatedatetime::timestamptz at time zone 'US/Central'    as updatedatetime,        completeddatetime::timestamptz at time zone 'US/Central' as completeddatetime,        writedatetime::timestamp,        userid::int,        ownerid::int,        previousownerid::int,        sendinguserid::int,        companyid,        destinationcompanyid,        exchangeconnectionid::bpchar,        contractdesc,        assetclass,        legcount::int,        round(price::bigint / 10000.0, 4)                        as price,        quantity::int,        filled::int,        round(avgprice::bigint / 100000000.0, 8)                 as avgprice,        stockquantity::bigint,        stockopenquantity::int,        stockfilled::int,        stockcancelled::bigint,        optionquantity::int,        optionopenquantity::int,        optionfilled::int,        optioncancelled::int,        invested::bigint,        accountalias,        account,        subaccount,        subaccount2,        subaccount3,        comment,        forwhom,        giveupfirm,        cmtafirm,        mpid,        sstkclid,        iscapstrategy,        iscrosslate,        isfbsamexoverrideprice,        isfbsamexratiospread,        isqcc,        islinked,        istargetedresplsmm,        istargetedresponse,        isauctionorder,        issolicited,        isallornone,        isnotheld,        istiedtostock,        pricequalifier,        timeinforcecode,        boothidoverride,        public.clordid_to_guid(linkorderid)                      as linkorderid,        ltargetresponseid,        satpid,        scrossbadgeids,        reasoncode::int,        parentorderidint,        cancelorderidint,        contraorderidint,        origorderidint,        generation::int,        childorders::int,        capacity,        portfolio,        exdestination,        prevfillquantity::int,        stockprevfillquantity::int,        optionprevfillquantity::int,        tradedate::text::date,        _order_id::bigint,        _chain_id::int,        _db_create_time::timestamptz at time zone 'US/Central'   as _db_create_time,        order_trade_date_id FROM blaze7.torder_edw as x where x.order_trade_date_id between  20250630 and public.get_dateid(public.get_business_date(20250630::text::date, 1)) AND (x._db_create_time::timestamp >  '2020-01-01 00:00:00'::timestamp at time zone 'US/Central' - interval '1 second' or x.orig_db_create_time::timestamp >  '2020-01-01 00:00:00'::timestamp at time zone 'US/Central' - interval '1 second' or x.rep_db_create_time::timestamp >  '2020-01-01 00:00:00'::timestamp at time zone 'US/Central'  - interval '1 second' ) 